CREATE TABLE public."User" (id uuid NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, username character varying, email character varying NOT NULL, password character varying NOT NULL);
ALTER TABLE public."User" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."User" ADD CONSTRAINT "User_email_key" UNIQUE (email);
ALTER TABLE public."User" ADD CONSTRAINT "User_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id);
ALTER TABLE public."User" ADD CONSTRAINT "User_pkey" PRIMARY KEY (id);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public."User" TO anon;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public."User" TO authenticated;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public."User" TO service_role;
CREATE TABLE public.collection (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, name character varying NOT NULL, description character varying, image character varying, slug text NOT NULL, title text);
ALTER TABLE public.collection ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.collection ADD CONSTRAINT collection_pkey PRIMARY KEY (id);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.collection TO anon;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.collection TO authenticated;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.collection TO service_role;
CREATE TABLE public.collection_product (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, id_product bigint, id_collection bigint);
ALTER TABLE public.collection_product ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.collection_product ADD CONSTRAINT collection_product_id_collection_fkey FOREIGN KEY (id_collection) REFERENCES public.collection(id);
ALTER TABLE public.collection_product ADD CONSTRAINT collection_product_pkey PRIMARY KEY (id);
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.collection_product TO anon;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.collection_product TO authenticated;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.collection_product TO service_role;
CREATE TABLE public.product (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, name character varying NOT NULL, rate smallint, image character varying, price real, description character varying, short character varying, slug text NOT NULL);
ALTER TABLE public.product ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product ADD CONSTRAINT product_pkey PRIMARY KEY (id);
ALTER TABLE public.collection_product ADD CONSTRAINT collection_product_id_product_fkey FOREIGN KEY (id_product) REFERENCES public.product(id);
GRANT MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE ON public.product TO anon;
GRANT ALL ON public.product TO authenticated;
GRANT MAINTAIN, REFERENCES, TRIGGER, TRUNCATE ON public.product TO service_role;
CREATE POLICY "Public read access on product" ON public.product FOR SELECT TO anon, authenticated USING (true);
